var n=`0909-red-braised-pork-belly`;var a=`world-0909`;var s=`CN`;var t=`east-asia`;var r=4;var o=123;var d={en:`Red-Braised Pork Belly`,ua:`Тушкована свиняча грудинка хуншао`};var l={en:`Red-Braised Pork Belly is a China dish made with pork belly, green onion, light soy sauce, dark soy sauce. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Тушкована свиняча грудинка хуншао, страва кухні країни Китай. Основні складники: свиняча грудинка, зелена цибуля, світлий соєвий соус, темний соєвий соус. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 13 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 13 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:13,i:[[`pork-belly`,900,`g`],[`canola-oil`,45,`ml`],[`white-granulated-sugar`,70,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 6 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 6 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:6,i:[[`ground-ginger`,25,`g`],[`green-onion`,70,`g`],[`star-anise`,3,`pcs`]]},{en:`Add soy sauces and Shaoxing wine to caramelized pork belly and gently red-braise covered until tender and glossy, about 90 minutes.`,ua:`Додайте соєві соуси й шаосінське вино до карамелізованої грудинки та повільно тушкуйте під кришкою до м’якості й блиску близько 90 хвилин.`,t:[`red-braising`],m:90,i:[[`shaoxing-wine`,80,`ml`],[`light-soy-sauce`,50,`ml`],[`dark-soy-sauce`,25,`ml`],[`water`,700,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 12 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 12 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:12,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`green-onion`,25,`g`]]}];var u={slug:n,id:a,country:`CN`,region:t,servings:4,minutes:123,title:d,text:l,steps:g};export{s as country,u as default,a as id,o as minutes,t as region,r as servings,n as slug,g as steps,l as text,d as title};